export default function ContactForm() {
  async function submitContact(formData: FormData) {
    'use server';

    const name = formData.get('name');
    const email = formData.get('email');
    const message = formData.get('message');

    if (!name || !email || !message) {
      throw new Error('Please provide all fields: name, email, and message.');
    }

    // In a real application, you would save the data here
    console.log('Contact form submitted:', { name, email, message });
  }

  return (
    <form action={submitContact} style={{ display: 'flex', flexDirection: 'column', gap: '1rem', maxWidth: '400px' }}>
      <div>
        <label htmlFor="name" style={{ display: 'block', marginBottom: '0.5rem' }}>Name</label>
        <input type="text" id="name" name="name" style={{ width: '100%', padding: '0.5rem' }} />
      </div>

      <div>
        <label htmlFor="email" style={{ display: 'block', marginBottom: '0.5rem' }}>Email</label>
        <input type="email" id="email" name="email" style={{ width: '100%', padding: '0.5rem' }} />
      </div>

      <div>
        <label htmlFor="message" style={{ display: 'block', marginBottom: '0.5rem' }}>Message</label>
        <textarea id="message" name="message" rows={4} style={{ width: '100%', padding: '0.5rem' }} />
      </div>

      <button type="submit" style={{ padding: '0.5rem 1rem', background: '#0070f3', color: 'white', border: 'none', cursor: 'pointer' }}>
        Send Message
      </button>
    </form>
  );
}

